import json
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    for pv in range(1,H+1):
        for pw in range(1,W+1):
            m={}
            ok=True
            for r in range(H):
                for c in range(W):
                    if g[r][c]!=5:
                        k=(r%pv,c%pw); v=g[r][c]
                        if k in m and m[k]!=v: ok=False;break
                        m[k]=v
                if not ok:break
            if not ok:continue
            # fill 5s from pattern
            out=[r[:] for r in g]
            for r in range(H):
                for c in range(W):
                    if g[r][c]==5: out[r][c]=m[(r%pv,c%pw)]
            return out
